import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{or as n,t as r,wn as i}from"./icons-BIn1f5H-.js";import{n as a,t as o}from"./ArticleLayout-Kv_eBS_f.js";var s,c,l=e((()=>{r(),s=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Vendre sa voiture : comment et quand résilier votre assurance auto ?`,description:`Le contrat est suspendu à minuit le soir de la vente, mais pas résilié pour autant. Délai, lettre recommandée et remboursement expliqués.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/resilier-assurance-apres-vente-voiture`,datePublished:`2026-09-10`,dateModified:`2026-09-10`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Résilier son assurance après une vente`,item:`https://assutempo.fr/articles/resilier-assurance-apres-vente-voiture`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Quand mon assurance auto s'arrête-t-elle après la vente de ma voiture ?`,acceptedAnswer:{"@type":`Answer`,text:`Le contrat est suspendu de plein droit dès le soir de la vente, à minuit, sans démarche particulière pour cette suspension. Ce n'est toutefois pas une résiliation : elle doit être demandée séparément.`}},{"@type":`Question`,name:`Comment résilier son assurance après une vente entre particuliers ?`,acceptedAnswer:{"@type":`Answer`,text:`Par lettre recommandée (ou recommandé électronique) à l'assureur, avec vos coordonnées, le numéro de contrat, la date de vente, l'immatriculation et une copie du certificat de cession (Cerfa n°15776). La résiliation prend effet 10 jours calendaires après réception de ce courrier par l'assureur.`}},{"@type":`Question`,name:`Vais-je être remboursé de ma cotisation ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui. La part de cotisation déjà payée pour la période postérieure à la fin de l'assurance vous est remboursée.`}},{"@type":`Question`,name:`Mon contrat se transmet-il automatiquement à l'acheteur ?`,acceptedAnswer:{"@type":`Answer`,text:`Non, dans la grande majorité des cas. L'acheteur doit souscrire son propre contrat avant de prendre la route, y compris pour le trajet retour.`}},{"@type":`Question`,name:`Que devient mon bonus-malus si je reste un moment sans véhicule ?`,acceptedAnswer:{"@type":`Answer`,text:`En dessous de 3 mois d'interruption et sans sinistre responsable dans l'année, votre bonus s'améliore encore de 5 % à la souscription du contrat suivant. Au-delà de 3 mois, le coefficient acquis avant la vente est conservé, mais l'assureur peut vous traiter comme un nouveau conducteur si l'interruption est très longue.`}},{"@type":`Question`,name:`Comment assurer un nouveau véhicule en attendant de retrouver un contrat annuel ?`,acceptedAnswer:{"@type":`Answer`,text:`Une assurance temporaire, de 1 à 90 jours, couvre le véhicule dès la remise des clés, le temps de comparer et signer un contrat annuel adapté.`}}]}],c={slug:`resilier-assurance-apres-vente-voiture`,seo:{title:`Résilier son assurance après la vente d'une voiture`,description:`Vous vendez votre voiture ? Le contrat est suspendu à minuit le soir même. Délai de résiliation, lettre type et remboursement, expliqués.`,canonical:`https://assutempo.fr/articles/resilier-assurance-apres-vente-voiture`,jsonLd:s},category:`Vente véhicule`,readTime:`7 min`,updatedDate:`10 septembre 2026`,author:`Evidence Assurances`,headline:`Vendre sa voiture : comment et quand résilier votre assurance auto ?`,cta:{href:`/tarification`,label:`Assurer mon nouveau véhicule`,title:`Vous venez de racheter un véhicule ?`,subtitle:`Assurez-le en 5 minutes le temps de retrouver un contrat annuel.`,suffix:`Attestation immédiate, de 1 à 90 jours.`},answerCapsule:{answer:`Votre contrat d'assurance auto est suspendu de plein droit à minuit, le soir de la vente, sans démarche à faire pour cela. Mais pour résilier réellement le contrat et être remboursé du trop-perçu, il faut prévenir l'assureur par lettre recommandée avec le certificat de cession (Cerfa n°15776) : la résiliation prend effet 10 jours calendaires après réception (service-public.gouv.fr).`,facts:[{anchor:`Minuit, le soir de la vente`,text:`Le contrat est suspendu de plein droit dès la vente, sans aucune démarche pour cette suspension (service-public.gouv.fr).`},{anchor:`10 jours calendaires`,text:`Délai après lequel la résiliation prend effet, une fois la lettre recommandée reçue par l'assureur.`},{anchor:`Cerfa n°15776`,text:`Certificat de cession à joindre à la lettre, avec le numéro de contrat, la date de vente et l'immatriculation du véhicule.`}],updated:`10 septembre 2026`},sections:[{type:`alert`,heading:`L'essentiel`,items:[`Le contrat d'assurance est suspendu de plein droit à minuit, le soir même de la vente : aucune démarche n'est nécessaire pour cette suspension.`,`Pour résilier réellement le contrat et arrêter d'être prélevé, une lettre recommandée à l'assureur reste nécessaire, avec le certificat de cession (Cerfa n°15776).`,`La résiliation prend effet 10 jours calendaires après réception de cette lettre par l'assureur (service-public.gouv.fr).`,`La part de cotisation déjà payée pour la période postérieure à la vente vous est remboursée.`]},{type:`text`,heading:`Ce qui se passe automatiquement, le soir de la vente`,paragraphs:[`Dès que la voiture change de mains, le contrat qui la couvrait bascule en suspension, à minuit le soir même. Cette suspension-là ne demande aucune démarche de votre part : elle joue de plein droit, à la date exacte de la cession (service-public.gouv.fr, fiche « Comment résilier l'assurance après avoir vendu son véhicule ? », vérifiée le 27 février 2025).`,`C'est là que beaucoup de vendeurs s'arrêtent, en pensant le dossier clos. Ce n'est pourtant que la moitié du chemin : suspendre n'est pas résilier, et tant que la résiliation n'est pas actée, le contrat continue d'exister sur le papier.`],relatedLink:{text:`De l'autre côté de la vente : ce que doit faire l'acheteur`,href:`/articles/assurer-vehicule-achete-chez-particulier`}},{type:`text`,heading:`Pourquoi il faut quand même écrire à l'assureur`,paragraphs:[`La suspension protège le véhicule vendu, pas votre budget. Pour arrêter d'être prélevé et récupérer la part de cotisation qui correspond à la période où vous n'êtes plus assuré, il faut notifier l'assureur par lettre recommandée, ou par un envoi recommandé électronique s'il l'accepte.`,`Aucun délai maximal n'est fixé par les textes pour cet envoi. Mieux vaut malgré tout ne pas traîner : c'est la réception de cette lettre par l'assureur qui déclenche le compte à rebours de la résiliation, et donc du remboursement.`]},{type:`checklist`,heading:`Ce que doit contenir la lettre de résiliation`,items:[`Vos coordonnées et le numéro du contrat concerné`,`La date exacte de la vente`,`La marque et l'immatriculation du véhicule vendu`,`Une copie du certificat de cession (Cerfa n°15776), daté et signé par les deux parties`,`Un envoi en recommandé, postal ou électronique si l'assureur le propose`],note:`Source : service-public.gouv.fr, fiche « Comment résilier l'assurance après avoir vendu son véhicule ? », vérifiée le 27 février 2025.`},{type:`table`,heading:`Suspension automatique ou résiliation formelle : ce qui change`,intro:`Les deux étapes ne se confondent pas, et seule la seconde arrête la facturation.`,columns:[``,`Suspension`,`Résiliation`],rows:[[`Quand`,`Le soir de la vente, à minuit`,`10 jours calendaires après réception de la lettre par l'assureur`],[`Démarche`,`Aucune, elle joue de plein droit`,`Lettre recommandée avec le certificat de cession (Cerfa n°15776)`],[`Effet`,`Le contrat cesse de garantir le véhicule vendu`,`Fin du contrat et remboursement du trop-perçu de cotisation`]],note:`Source : service-public.gouv.fr, fiche « Comment résilier l'assurance après avoir vendu son véhicule ? », vérifiée le 27 février 2025.`},{type:`decisionsplit`,question:`Que devient votre bonus-malus après la vente ?`,ariaLabel:`Comparaison entre reprendre un véhicule sous 3 mois (bonus amélioré de 5 % supplémentaires) et rester sans véhicule plus de 3 mois (coefficient conservé, mais statut de nouveau conducteur possible si l'interruption est très longue)`,voies:[{statut:`ok`,icon:i,titre:`Vous reprenez un véhicule sous 3 mois`,verdict:`Sans sinistre responsable dans l'année écoulée, votre bonus s'améliore encore de 5 % à la souscription du contrat suivant (service-public.gouv.fr).`},{statut:`vigilance`,icon:n,titre:`Vous restez sans véhicule plus de 3 mois`,verdict:`Le coefficient acquis avant la vente est conservé, mais l'assureur peut vous considérer comme un nouveau conducteur si l'interruption est très longue.`}]},{type:`text`,heading:`Et si vous rachetez un véhicule tout de suite ?`,paragraphs:[`La revente s'accompagne souvent d'un rachat, parfois le jour même. La règle ne change pas d'un vendeur à l'autre : le nouveau véhicule doit être assuré à votre nom dès la remise des clés, aucun délai de grâce ne couvre le trajet retour.`,`Si le contrat annuel visé demande quelques jours de comparaison ou de signature, une assurance temporaire, à la journée près, de 1 à 90 jours, couvre cette transition sans vous engager sur l'année.`],relatedLink:{text:`Assurance trajet retour après achat voiture`,href:`/articles/assurance-trajet-retour-achat-voiture`}},{type:`text`,heading:`Le contrat se transmet-il à l'acheteur ?`,paragraphs:[`Dans la grande majorité des cas, non : l'assureur ne transfère pas votre contrat à un autre conducteur (service-public.gouv.fr). L'acheteur doit souscrire sa propre assurance avant de prendre le volant, y compris pour le tout premier trajet.`,`Le même principe s'applique en amont de la vente : si un acheteur potentiel souhaite essayer le véhicule avant de se décider, cet essai doit lui aussi être couvert, séparément du contrat qui touche à sa fin.`],relatedLink:{text:`Essayer un véhicule avant achat, bien assuré`,href:`/articles/assurance-temporaire-essai-vehicule-avant-achat`}},{type:`text`,heading:`Ce qu'il faut retenir`,paragraphs:[`Vendre sa voiture arrête la garantie le soir même, mais pas le contrat sur le papier : seule une lettre recommandée avec le certificat de cession déclenche la résiliation, dix jours calendaires plus tard, et le remboursement qui va avec. Pendant ce temps, si un nouveau véhicule prend le relais, il se couvre dès la remise des clés, au besoin avec une formule temporaire le temps de choisir le bon contrat annuel.`],relatedLink:{text:`Le rétroplanning complet après un achat de véhicule`,href:`/roulez-legal-apres-achat`}}],faqItems:[{q:`Quand mon assurance auto s'arrête-t-elle après la vente de ma voiture ?`,a:`Le contrat est suspendu de plein droit dès le soir de la vente, à minuit, sans démarche particulière. Ce n'est pas encore une résiliation.`},{q:`Comment résilier son assurance après une vente entre particuliers ?`,a:`Par lettre recommandée avec vos coordonnées, le numéro de contrat, la date de vente et une copie du certificat de cession (Cerfa n°15776). Effet 10 jours calendaires après réception.`},{q:`Vais-je être remboursé de ma cotisation ?`,a:`Oui, la part correspondant à la période postérieure à la fin de l'assurance vous est remboursée.`},{q:`Mon contrat se transmet-il automatiquement à l'acheteur ?`,a:`Non, dans la grande majorité des cas. L'acheteur doit souscrire son propre contrat avant de prendre la route.`},{q:`Que devient mon bonus-malus si je reste un moment sans véhicule ?`,a:`Sous 3 mois et sans sinistre, le bonus s'améliore encore de 5 %. Au-delà, le coefficient est conservé, sauf interruption très longue.`},{q:`Comment assurer un nouveau véhicule en attendant un contrat annuel ?`,a:`Une assurance temporaire, de 1 à 90 jours, couvre le véhicule dès la remise des clés.`}]}}));function u(){return(0,d.jsx)(o,{data:c})}var d;e((()=>{a(),l(),d=t()}))();export{u as default};